struct ObfuscatedTO: Codable, CustomStringConvertible {
    let id: String
    private(set) var sealed: Data?                   // AES.GCM.SealedBox.combined

    mutating func seal(_ protectedMap: [String: String], key: SymmetricKey) throws {
        sealed = try AES.GCM.seal(JSONEncoder().encode(protectedMap), using: key).combined
    }
    func unseal(key: SymmetricKey) throws -> [String: String] {
        guard let sealed else { return [:] }
        let box = try AES.GCM.SealedBox(combined: sealed)
        return try JSONDecoder().decode([String: String].self, from: AES.GCM.open(box, using: key))
    }
    var description: String { "ObfuscatedTO(id: \(id))" }   // never sealed or plaintext
}
